<template>
	<div class="flex min-h-dvh flex-col bg-ui-canvas">
		<!-- ===== Header + Filter (sticky, tidak ikut scroll) ===== -->
		<div class="sticky top-0 z-20">
			<div class="bg-ui-surface">
				<div
					class="flex items-center gap-2 px-5 py-4"
					style="padding-top: calc(1rem + env(safe-area-inset-top))"
				>
					<button
						type="button"
						@click="goBack"
						class="-ml-2 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
						aria-label="Kembali"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-7 w-7"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="m12 19-7-7 7-7" />
							<path d="M19 12H5" />
						</svg>
					</button>
					<h1 class="text-xl font-semibold text-ui-heading">Approval Requests</h1>
				</div>
			</div>
			<div class="bg-ui-canvas px-5 pb-3 pt-4">
				<!-- ===== Filter document type ===== -->
				<div class="relative">
					<button
						type="button"
						@click="filterOpen = !filterOpen"
						class="flex w-full appearance-none items-center gap-3 rounded-full border border-ui-line-slate-300 bg-ui-surface px-5 py-3.5 active:bg-ui-surface-slate-50"
					>
						<svg
							class="h-6 w-6 shrink-0 text-ui-subtle"
							viewBox="0 0 24 24"
							fill="none"
							xmlns="http://www.w3.org/2000/svg"
						>
							<path
								d="M3 5h18l-7 8v6l-4 2v-8L3 5Z"
								stroke="currentColor"
								stroke-width="1.7"
								stroke-linejoin="round"
							/>
						</svg>
						<span
							class="flex-1 truncate text-left text-lg font-semibold text-ui-heading"
							>{{ selectedLabel }}</span
						>
						<svg
							class="h-5 w-5 shrink-0 text-ui-subtle transition-transform"
							:class="{ 'rotate-180': filterOpen }"
							viewBox="0 0 24 24"
							fill="none"
							xmlns="http://www.w3.org/2000/svg"
						>
							<path
								d="m6 9 6 6 6-6"
								stroke="currentColor"
								stroke-width="2"
								stroke-linecap="round"
								stroke-linejoin="round"
							/>
						</svg>
					</button>

					<!-- Panel opsi -->
					<template v-if="filterOpen">
						<div class="fixed inset-0 z-20" @click="filterOpen = false"></div>
						<div
							class="absolute left-0 right-0 z-30 mt-2 overflow-hidden rounded-2xl border border-ui-line-slate-200 bg-ui-surface py-1 shadow-lg"
						>
							<button
								v-for="opt in filterOptions"
								:key="opt.value"
								type="button"
								@click="selectFilter(opt.value)"
								class="block w-full appearance-none px-5 py-3 text-left text-base font-medium hover:bg-ui-surface-slate-50"
								:class="opt.value === selected ? 'text-primary' : 'text-ui-heading'"
							>
								{{ opt.label }}
							</button>
						</div>
					</template>
				</div>
			</div>
		</div>

		<main
			class="app-container flex-1 px-5 pt-4"
			style="padding-bottom: calc(2rem + env(safe-area-inset-bottom))"
		>
			<!-- ===== Loading ===== -->
			<div v-if="loading && !res.data" class="flex justify-center pt-12">
				<svg
					class="h-6 w-6 animate-spin text-primary"
					viewBox="0 0 24 24"
					fill="none"
					xmlns="http://www.w3.org/2000/svg"
				>
					<circle
						cx="12"
						cy="12"
						r="9"
						stroke="currentColor"
						stroke-width="2"
						stroke-opacity="0.25"
					/>
					<path
						d="M21 12a9 9 0 0 0-9-9"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
					/>
				</svg>
			</div>

			<!-- ===== Empty ===== -->
			<div
				v-else-if="!filteredItems.length"
				class="flex items-center justify-center rounded-[1.5rem] bg-ui-surface px-6 py-20 shadow-sm"
			>
				<p class="text-center text-lg font-medium text-ui-ink-slate-400">
					No Workflow Requests Found !
				</p>
			</div>

			<!-- ===== List ===== -->
			<div v-else class="card-grid">
				<component
					:is="detailTo(item) ? RouterLink : 'div'"
					v-for="item in filteredItems"
					:key="item.doctype + ':' + item.name"
					:to="detailTo(item)"
					class="block rounded-xl border border-ui-line-gray-200 bg-ui-surface p-4 shadow-sm"
					:class="detailTo(item) ? 'active:bg-ui-surface-gray-50' : ''"
				>
					<!-- Baris atas: ID + label doctype (warna teks beda per tipe request) -->
					<div class="flex items-start justify-between gap-2">
						<p
							class="min-w-0 truncate text-sm font-bold"
							:class="typeTextClass(item.doctype)"
						>
							{{ idLabel(item) }}
						</p>
						<span
							class="shrink-0 rounded-full px-2.5 py-0.5 text-xs font-bold"
							:class="typeBadgeClass(item.doctype)"
							>{{ item.doctype }}</span
						>
					</div>

					<!-- Tanggal -->
					<p class="mt-0.5 text-xs text-ui-ink-gray-400">{{ formatDate(item.tanggal) }}</p>

					<!-- Nama/judul (di bawah tanggal) + status. Judul disembunyikan bila kosong. -->
					<div class="mt-3 flex items-center justify-between gap-2">
						<span
							v-if="item.nama"
							class="min-w-0 truncate text-sm font-semibold"
							:class="typeTextClass(item.doctype)"
							>{{ item.nama }}</span
						>
						<span v-else class="min-w-0"></span>
						<span
							class="shrink-0 rounded-full px-2.5 py-1 text-xs font-medium"
							:class="STATUS_BADGE"
							>{{ item.status || '—' }}</span
						>
					</div>

					<!-- Pemisah -->
					<div class="my-3 border-t border-ui-line-gray-100"></div>

					<!-- Dua kolom bawah (beda per tipe) -->
					<div class="flex items-end justify-between gap-3">
						<div class="min-w-0">
							<p class="text-xs text-ui-ink-gray-400">{{ leftLabel(item) }}</p>
							<p class="mt-0.5 truncate text-sm font-semibold text-primary">
								{{ leftValue(item) }}
							</p>
						</div>
						<div v-if="rightLabel(item)" class="min-w-0 shrink-0 text-right">
							<p class="text-xs text-ui-ink-gray-400">{{ rightLabel(item) }}</p>
							<p class="mt-0.5 truncate text-sm font-bold text-primary">
								{{ rightValue(item) }}
							</p>
						</div>
					</div>
				</component>
			</div>
		</main>
	</div>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { useListPersistence } from '../composables/useListPersistence'
import { NAVIGATION_ORIGIN, withNavigationOrigin } from '../data/navigationOrigin.js'

const router = useRouter()
function goBack() {
	router.push({ name: 'Home' })
}

const res = createResource({
	url: 'juragan.api.portal.workflow_requests.get_workflow_requests',
	method: 'GET',
	auto: true,
})
const loading = computed(() => res.loading)
const items = computed(() => res.data?.items || [])
const listPersistence = useListPersistence('WorkflowRequests')

// ===== Filter document type =====
const filterOpen = ref(false)
const selected = ref(listPersistence.readSession({ selected: '' }).selected) // '' = All
const filterOptions = computed(() => [
	{ label: 'All', value: '' },
	...(res.data?.filters || []).map((f) => ({ label: f, value: f })),
])
const selectedLabel = computed(
	() => filterOptions.value.find((o) => o.value === selected.value)?.label || 'All'
)
function selectFilter(v) {
	selected.value = v
	listPersistence.writeSession({ selected: v })
	filterOpen.value = false
}
watch(
	() => res.data?.filters,
	(filters) => {
		if (!filters || !selected.value) return
		if (!filters.includes(selected.value)) {
			selected.value = ''
			listPersistence.writeSession({ selected: '' })
		}
	},
	{ immediate: true },
)
const filteredItems = computed(() =>
	selected.value ? items.value.filter((i) => i.doctype === selected.value) : items.value
)

// ===== Navigasi ke detail dokumen =====
// SEMUA kartu request mengarah ke halaman detail dokumennya saat ditekan
// (perilaku sama seperti Data Pengajuan). Doctype yang belum punya halaman
// detail di portal → kartu tetap tampil tapi tidak bisa diklik.
const DETAIL_ROUTE = {
	'Data Pengajuan': 'DataPengajuanDetail',
	Deviasi: 'DeviasiDetail',
	BSTK: 'BstkDetail',
	TTS: 'TtsDetail',
	'Surat Diskresi': 'DiskresiDetail',
	'Master Data Nasabah': 'MasterDataNasabahDetail',
	'Tebus Motor Nasabah': 'TebusMotorDetail',
	'Request AYDA Motor': 'RequestAydaDetail',
	'Oper PIC': 'OperPicDetail',
}
// Sebagian doctype diputuskan dari halaman DAFTARNYA, bukan dari satu dokumen
// lepas. Keterlambatan begitu: keputusannya butuh konteks periode cut-off dan
// riwayat orangnya, dan itu semua ada di antrean — bukan di satu record.
const LIST_ROUTE = {
	Keterlambatan: 'KeterlambatanKetua',
}
function detailTo(item) {
	const daftar = LIST_ROUTE[item.doctype]
	if (daftar) {
		return withNavigationOrigin(
			{ name: daftar },
			NAVIGATION_ORIGIN.APPROVAL_REQUESTS,
		)
	}

	const route = DETAIL_ROUTE[item.doctype]
	return route
		? withNavigationOrigin(
				{ name: route, params: { name: item.name } },
				NAVIGATION_ORIGIN.APPROVAL_REQUESTS,
			)
		: undefined
}

// ===== Warna per tipe request =====
// Semua status request → abu-abu (badge ber-background).
const STATUS_BADGE = 'bg-ui-surface-gray-100 text-ui-ink-gray-600'

// Warna KHUSUS untuk tipe utama + palet fallback (di-hash dari nama doctype)
// supaya SETIAP tipe request punya warna teks yang berbeda. `badge` = bg+teks
// pill doctype; `text` = warna teks judul kartu.
const TYPE_OVERRIDE = {
	'Data Pengajuan': { badge: 'bg-ui-success-soft text-ui-success', text: 'text-ui-success' },
	Deviasi: { badge: 'bg-ui-surface-yellow-100 text-ui-ink-yellow-700', text: 'text-ui-ink-yellow-700' },
	'Surat Diskresi': { badge: 'bg-ui-surface-purple-100 text-ui-ink-purple-700', text: 'text-ui-ink-purple-700' },
	'Tebus Motor Nasabah': { badge: 'bg-ui-surface-teal-100 text-ui-ink-teal-700', text: 'text-ui-ink-teal-700' },
	'Request AYDA Motor': { badge: 'bg-ui-surface-violet-100 text-ui-ink-violet-700', text: 'text-ui-ink-violet-700' },
	'Oper PIC': { badge: 'bg-ui-surface-indigo-100 text-ui-ink-indigo-700', text: 'text-ui-ink-indigo-700' },
}
const TYPE_PALETTE = [
	{ badge: 'bg-ui-surface-blue-100 text-ui-ink-blue-700', text: 'text-ui-ink-blue-700' },
	{ badge: 'bg-ui-surface-pink-100 text-ui-ink-pink-700', text: 'text-ui-ink-pink-700' },
	{ badge: 'bg-ui-surface-orange-100 text-ui-ink-orange-700', text: 'text-ui-ink-orange-700' },
	{ badge: 'bg-ui-surface-cyan-100 text-ui-ink-cyan-700', text: 'text-ui-ink-cyan-700' },
	{ badge: 'bg-ui-surface-amber-100 text-ui-ink-amber-700', text: 'text-ui-ink-amber-700' },
	{ badge: 'bg-ui-surface-violet-100 text-ui-ink-violet-700', text: 'text-ui-ink-violet-700' },
	{ badge: 'bg-ui-surface-teal-100 text-ui-ink-teal-700', text: 'text-ui-ink-teal-700' },
	{ badge: 'bg-ui-surface-purple-100 text-ui-ink-purple-700', text: 'text-ui-ink-purple-700' },
]
function typeStyle(doctype) {
	if (TYPE_OVERRIDE[doctype]) return TYPE_OVERRIDE[doctype]
	let h = 0
	for (let i = 0; i < doctype.length; i++) h = (h * 31 + doctype.charCodeAt(i)) >>> 0
	return TYPE_PALETTE[h % TYPE_PALETTE.length]
}
function typeBadgeClass(doctype) {
	return typeStyle(doctype).badge
}
function typeTextClass(doctype) {
	return typeStyle(doctype).text
}

// Teks sudut kiri atas kartu. Umumnya ID dokumen; khusus Oper PIC tampilkan
// JENIS dokumen induk (TTS/BSTK) agar keduanya langsung terpisah sekilas.
function idLabel(item) {
	if (item.doctype === 'Oper PIC') return item.jenis_dokumen || item.name
	return item.name
}

// ===== Kolom bawah per tipe (doctype lain → generik: Dibuat oleh) =====
function leftLabel(item) {
	switch (item.doctype) {
		case 'Data Pengajuan':
			return 'Nama Marketing'
		case 'Deviasi':
			return 'Cabang'
		case 'Tebus Motor Nasabah':
			return 'Nama Nasabah'
		case 'Surat Diskresi':
			return 'Nama Marketing'
		case 'Request AYDA Motor':
			return 'Cabang'
		case 'Oper PIC':
			return 'PIC Lama'
		default:
			return 'Dibuat oleh'
	}
}
function leftValue(item) {
	switch (item.doctype) {
		case 'Data Pengajuan':
			return item.marketing_full_name || '—'
		case 'Deviasi':
			return item.cabang || '—'
		case 'Tebus Motor Nasabah':
			return item.nama_nasabah || '—'
		case 'Surat Diskresi':
			return item.nama_marketing || '—'
		case 'Request AYDA Motor':
			return item.cabang || '—'
		case 'Oper PIC':
			return item.nama_pic_lama || '—'
		default:
			return item.owner || '—'
	}
}
function rightLabel(item) {
	switch (item.doctype) {
		case 'Data Pengajuan':
			return 'Pinjaman'
		case 'Deviasi':
			return 'Jenis Deviasi'
		case 'Tebus Motor Nasabah':
			return 'Admin Tebus'
		case 'Surat Diskresi':
			return 'Referensi'
		case 'Request AYDA Motor':
			return 'Total Sisa Pokok'
		case 'Oper PIC':
			return 'PIC Baru'
		default:
			return ''
	}
}
function rightValue(item) {
	switch (item.doctype) {
		case 'Data Pengajuan':
			return formatMoney(item.pinjam)
		case 'Deviasi':
			return item.jenis_deviasi || '—'
		case 'Tebus Motor Nasabah':
			return formatMoney(item.nominal_tebus)
		case 'Surat Diskresi':
			return item.reference_name || '—'
		case 'Request AYDA Motor':
			return formatMoney(item.total_sisa_pokok)
		case 'Oper PIC':
			return item.nama_pic_baru || '—'
		default:
			return ''
	}
}

// ===== Format =====
const ID_MONTHS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'Mei',
	'Jun',
	'Jul',
	'Agu',
	'Sep',
	'Okt',
	'Nov',
	'Des',
]
function formatDate(v) {
	if (!v) return '—'
	const d = new Date(v)
	if (isNaN(d)) return String(v)
	return `${d.getDate()} ${ID_MONTHS[d.getMonth()]} ${d.getFullYear()}`
}
function formatMoney(v) {
	return 'Rp ' + (Number(v) || 0).toLocaleString('id-ID')
}
</script>
